import { test, expect } from '@playwright/test';

test.describe('Accessibility - Prefers Reduced Motion', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://your-app-url.com');
  });

  test('should respect prefers-reduced-motion setting', async ({ page }) => {
    await page.evaluate(() => {
      // Simulate prefers-reduced-motion setting
      Object.defineProperty(window, 'matchMedia', {
        value: (query) => ({
          matches: query.includes('prefers-reduced-motion: reduce'),
          media: query,
          onchange: null,
          addListener: () => {},
          removeListener: () => {},
        }),
      });
    });

    const animationElement = page.getByRole('animated-element'); // Replace with actual role
    await expect(animationElement).toHaveCSS('animation', 'none');
  });

  test('should not apply animations when prefers-reduced-motion is set', async ({ page }) => {
    await page.evaluate(() => {
      // Simulate prefers-reduced-motion setting
      Object.defineProperty(window, 'matchMedia', {
        value: (query) => ({
          matches: query.includes('prefers-reduced-motion: reduce'),
          media: query,
          onchange: null,
          addListener: () => {},
          removeListener: () => {},
        }),
      });
    });

    const button = page.getByRole('button', { name: 'Submit' }); // Replace with actual button name
    await button.click();

    const resultElement = page.getByText('Submission Successful'); // Replace with actual text
    await expect(resultElement).toBeVisible();
    await expect(resultElement).toHaveCSS('animation', 'none');
  });
});
